contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string memory typeStr) public payable {
        uint before = c.proposalCount();
        c.newAddressProposal(address(this), typeStr);
        uint afterCount = c.proposalCount();
        string memory recordedType = c.mapPID_type(afterCount);
        address recordedAddr = c.mapPID_address(afterCount);
        assert(afterCount == before + 1 && keccak256(bytes(recordedType)) == keccak256(bytes(typeStr)) && recordedAddr == address(this));
    }

    receive() external payable {}
}

