contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        require(recipient != address(0) || recipient == address(0));

        c.init(address(0x1), address(0x2), address(0x3));

        uint beforeCount = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint newId = beforeCount + 1;

        (address rec, uint amt) = c.mapPID_grant(newId);

        assert(c.proposalCount() == newId && c.mapPID_type(newId) == "GRANT" && rec == recipient && amt == amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        require(recipient != address(0) || recipient == address(0));

        c.init(address(0x1), address(0x2), address(0x3));

        uint beforeCount = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint newId = beforeCount + 1;

        (address rec, uint amt) = c.mapPID_grant(newId);

        bytes32 typeHash = sha256(bytes(c.mapPID_type(newId)));
        bytes32 expectedHash = sha256(bytes("GRANT"));

        assert(c.proposalCount() == newId && typeHash == expectedHash && rec == recipient && amt == amount);
    }

    receive() external payable {}
}
